(() => {
const WEAPONS = [
  { name: 'Glock-18', rarity: 'ШИРОКИЙ ВЖИТОК', color: '#a5b5bc', radius: 25, type: 'glock' },
  { name: 'USP-S', rarity: 'ПРОМИСЛОВА ЯКІСТЬ', color: '#80adcb', radius: 30, type: 'usp' },
  { name: 'Desert Eagle', rarity: 'АРМІЙСЬКА ЯКІСТЬ', color: '#6b95e6', radius: 36, type: 'deagle' },
  { name: 'MP9', rarity: 'АРМІЙСЬКА ЯКІСТЬ', color: '#8180e7', radius: 42, type: 'mp9' },
  { name: 'P90', rarity: 'ЗАБОРОНЕНА', color: '#a27be0', radius: 48, type: 'p90' },
  { name: 'FAMAS', rarity: 'ЗАБОРОНЕНА', color: '#c879dc', radius: 54, type: 'famas' },
  { name: 'M4A1-S', rarity: 'ЗАСЕКРЕЧЕНА', color: '#e17eaf', radius: 60, type: 'm4' },
  { name: 'AK-47', rarity: 'ТАЄМНА', color: '#e77666', radius: 67, type: 'ak' },
  { name: 'AWP', rarity: 'ТАЄМНА', color: '#ef9a53', radius: 74, type: 'awp' },
  { name: 'Karambit', rarity: '★ ЛЕГЕНДАРНА', color: '#efc762', radius: 82, type: 'knife' },
];

class World {
  constructor(width = 520, height = 630, onMerge = () => {}) {
    this.width = width; this.height = height; this.onMerge = onMerge;
    this.bodies = []; this.nextId = 0; this.score = 0; this.merges = 0;
    this.dangerTime = 0; this.over = false;
  }
  add(tier, x, y = 48) {
    const r = WEAPONS[tier].radius;
    const body = { id: this.nextId++, tier, r, x: Math.max(r + 9, Math.min(this.width - r - 9, x)), y, vx: 0, vy: 0, omega: 0, age: 0, angle: 0, born: 0, merged: false };
    this.bodies.push(body); return body;
  }
  step(dt = 1) {
    if (this.over) return;
    for (const b of this.bodies) {
      b.age += dt; b.born += dt; b.vy = Math.min(10, b.vy + .22 * dt);
      b.vx *= Math.pow(.999, dt); b.omega *= Math.pow(.999, dt);
      b.x += b.vx * dt; b.y += b.vy * dt;
    }
    for (let pass = 0; pass < 8; pass++) {
      for (const b of this.bodies) {
        if (b.x < b.r + 8) { b.x = b.r + 8; b.vx = Math.abs(b.vx) * .25; }
        if (b.x > this.width - b.r - 8) { b.x = this.width - b.r - 8; b.vx = -Math.abs(b.vx) * .25; }
        if (b.y > this.height - b.r - 8) {
          b.y = this.height - b.r - 8;
          // Friction transfers sideways motion into clockwise rotation on the floor.
          const limit = .45 * (Math.max(0, b.vy) * 1.12);
          const friction = Math.max(-limit, Math.min(limit, -(b.vx - b.omega * b.r) / 3));
          b.vx += friction; b.omega -= 2 * friction / b.r;
          b.vy = -Math.abs(b.vy) * .12;
          if (pass === 0) { b.vx *= Math.pow(.992, dt); b.omega *= Math.pow(.992, dt); }
        }
      }
      const consumed = new Set(); const results = [];
      for (let i = 0; i < this.bodies.length; i++) for (let j = i + 1; j < this.bodies.length; j++) {
        const a = this.bodies[i], b = this.bodies[j];
        if (consumed.has(a.id) || consumed.has(b.id)) continue;
        let dx = b.x - a.x, dy = b.y - a.y;
        let distance = Math.hypot(dx, dy);
        if (distance >= a.r + b.r) continue;
        if (a.tier === b.tier) {
          consumed.add(a.id); consumed.add(b.id);
          const tier = a.tier + 1, points = 2 ** (tier + 2);
          this.score += points; this.merges++;
          results.push({ tier, x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, points,
            vx: (a.vx + b.vx) / 2, vy: (a.vy + b.vy) / 2,
            omega: (a.omega + b.omega) / 2, angle: a.angle, sourceRadius: a.r });
          continue;
        }
        if (distance < .001) { dx = 1; dy = 0; distance = 1; }
        const nx = dx / distance, ny = dy / distance, penetration = a.r + b.r - distance;
        const ia = 1 / (a.r * a.r), ib = 1 / (b.r * b.r), total = ia + ib;
        a.x -= nx * penetration * ia / total; a.y -= ny * penetration * ia / total;
        b.x += nx * penetration * ib / total; b.y += ny * penetration * ib / total;
        const velocity = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (velocity < 0) {
          const impulse = -1.12 * velocity / total;
          a.vx -= impulse * nx * ia; a.vy -= impulse * ny * ia;
          b.vx += impulse * nx * ib; b.vy += impulse * ny * ib;
          const tx = -ny, ty = nx;
          const slip = (b.vx - a.vx) * tx + (b.vy - a.vy) * ty - a.omega * a.r - b.omega * b.r;
          const friction = Math.max(-impulse * .28, Math.min(impulse * .28, -slip / (3 * total)));
          a.vx -= friction * tx * ia; a.vy -= friction * ty * ia;
          b.vx += friction * tx * ib; b.vy += friction * ty * ib;
          a.omega -= 2 * friction * ia / a.r;
          b.omega -= 2 * friction * ib / b.r;
        }
      }
      if (consumed.size) {
        this.bodies = this.bodies.filter(b => !consumed.has(b.id));
        for (const event of results) {
          if (event.tier < WEAPONS.length) {
            const body = this.add(event.tier, event.x, event.y);
            body.vx = event.vx; body.vy = Math.min(event.vy, 0) - .8;
            body.omega = event.omega * event.sourceRadius / body.r;
            body.angle = event.angle; body.age = 30; body.merged = true;
          }
          this.onMerge(event);
        }
      }
    }
    for (const b of this.bodies) b.angle += b.omega * dt;
    const danger = this.bodies.some(b => b.age > 100 && b.y - b.r < 112);
    this.dangerTime = danger ? this.dangerTime + dt : Math.max(0, this.dangerTime - dt * 3);
    if (this.dangerTime > 150) this.over = true;
  }
}


function poly(c, points, fill) {
  c.fillStyle = fill; c.beginPath();
  points.forEach(([x,y], i) => i ? c.lineTo(x,y) : c.moveTo(x,y)); c.closePath(); c.fill();
}
function rect(c,x,y,w,h,color) { c.fillStyle=color; c.fillRect(x,y,w,h); }

function drawWeapon(c, tier, x, y, width, angle = 0) {
  const w = WEAPONS[Math.min(tier,9)];
  c.save(); c.translate(x,y); c.rotate(angle); c.scale(width / 140,width / 140); c.translate(-70,-30);
  const steel = '#aab1ad', dark = '#424a48', light = '#d0d2c8', accent = w.color;
  c.lineJoin = 'round';
  if (tier <= 2) {
    const start = tier === 1 ? 8 : 26, end = tier === 1 ? 104 : 111;
    if(tier === 1) { rect(c,7,18,47,9,dark);rect(c,7,18,46,2,steel); }
    poly(c,[[tier===1?48:23,17],[end,17],[end+5,28],[103,32],[93,53],[72,51],[76,31],[start,30]],dark);
    poly(c,[[tier===1?48:23,16],[end,16],[end+2,25],[tier===1?48:23,25]],tier===2?light:steel);
    rect(c,tier===1?51:27,17,tier===1?45:72,3,accent);
    poly(c,[[81,30],[101,31],[91,50],[74,48]],'#303736');
    for(let j=0;j<4;j++)rect(c,88+j*4,20,2,6,'#596361');
    c.strokeStyle=steel;c.lineWidth=2;c.beginPath();c.moveTo(63,30);c.lineTo(64,39);c.lineTo(77,40);c.stroke();
    rect(c,31,12,4,5,dark);rect(c,99,12,4,5,dark);
  } else if(tier===9) {
    c.strokeStyle=light;c.lineWidth=8;c.beginPath();c.arc(95,18,9,0,Math.PI*2);c.stroke();
    poly(c,[[88,19],[100,27],[80,47],[67,46],[73,32]],'#434c47');
    poly(c,[[75,33],[66,47],[46,49],[31,40],[27,24],[34,12],[34,29],[45,36],[58,34],[66,26]],accent);
    poly(c,[[75,33],[66,47],[46,49],[31,40],[43,43],[61,41]],'#fff2b7');
    for(let i=0;i<3;i++)poly(c,[[78+i*5,27-i*4],[83+i*5,31-i*4],[78+i*5,35-i*4],[74+i*5,31-i*4]],'#899485');
  } else {
    const sniper=tier===8, bullpup=tier===4||tier===5;
    const barrelEnd=sniper?6: tier===6?3:16;
    rect(c,barrelEnd,24,55-barrelEnd,5,dark);rect(c,barrelEnd,24,55-barrelEnd,1,steel);
    if(tier===6) {rect(c,3,22,25,9,'#5f6a60');rect(c,4,22,24,2,steel);}
    poly(c,[[46,19],[101,19],[105,31],[55,34],[44,29]],steel);
    rect(c,47,20,53,4,accent);rect(c,50,29,47,4,dark);
    const stockColor=tier===7?'#976c48':dark;
    poly(c,[[99,23],[133,21],[134,40],[123,41],[102,31]],stockColor);
    poly(c,[[92,31],[102,33],[100,48],[92,48],[88,37]],dark);
    if(tier===7) {
      poly(c,[[70,32],[82,32],[81,43],[88,53],[77,55],[70,44]],'#6d7470');
      poly(c,[[35,22],[58,22],[58,31],[36,31]],'#a67b4f');
    } else if(tier===4) {
      poly(c,[[44,17],[113,16],[126,23],[126,40],[114,44],[106,31],[89,30],[84,43],[72,43],[64,31],[45,29]],'#9b9a7b');
      rect(c,49,14,53,5,accent);rect(c,55,22,43,4,dark);
    } else {
      poly(c,[[bullpup?105:67,31],[bullpup?116:79,31],[bullpup?113:77,48],[bullpup?103:64,48]],dark);
    }
    if(sniper) {
      rect(c,45,9,43,8,dark);rect(c,49,10,36,2,steel);rect(c,43,7,7,12,dark);rect(c,83,7,9,12,dark);
      rect(c,55,16,4,6,steel);rect(c,78,16,4,6,steel);rect(c,24,30,3,15,dark);
      poly(c,[[45,24],[105,24],[127,32],[128,41],[117,41],[99,30],[45,30]],'#849365');
    } else if(tier===5) {rect(c,64,9,42,4,steel);rect(c,66,12,3,8,dark);rect(c,101,12,3,8,dark);}
    else if(tier===3) {rect(c,61,9,27,7,dark);rect(c,47,31,6,17,dark);}
    else {rect(c,81,13,6,7,dark);rect(c,30,16,3,8,dark);}
    for(let j=0;j<5;j++)rect(c,50+j*5,25,2,3,'#3b4240');
    rect(c,89,25,8,2,light);
  }
  c.restore();
}

function drawCase(c, tier, x, y, radius, angle = 0, alpha = 1) {
  const w = WEAPONS[tier];
  c.save(); c.globalAlpha=alpha; c.translate(x,y); c.rotate(angle);
  c.shadowColor = '#0009'; c.shadowBlur=9; c.shadowOffsetY=4;
  const gradient = c.createLinearGradient(-radius,-radius,radius,radius);
  gradient.addColorStop(0,'#3a443c'); gradient.addColorStop(.5,'#202922'); gradient.addColorStop(1,'#151e18');
  c.fillStyle=gradient; c.strokeStyle=w.color+'99'; c.lineWidth=1.5;
  c.beginPath(); c.arc(0,0,radius-1,0,Math.PI*2); c.fill(); c.stroke();
  c.shadowBlur=0;c.shadowOffsetY=0;
  c.strokeStyle=w.color+'22';c.lineWidth=1;c.beginPath();c.arc(0,0,radius-5,0,Math.PI*2);c.stroke();
  c.fillStyle=w.color+'0c'; c.beginPath();c.arc(0,0,radius-6,0,Math.PI*2);c.fill();
  // Asymmetric rim markings make full rotations easy to see.
  c.strokeStyle=w.color+'bb';c.lineWidth=2;
  c.beginPath();c.arc(0,0,radius-4,-.5,.15);c.stroke();
  c.strokeStyle=w.color+'55';c.lineWidth=1.5;
  for(let i=0;i<3;i++){const a=2.2+i*.18;c.beginPath();c.moveTo(Math.cos(a)*(radius-7),Math.sin(a)*(radius-7));c.lineTo(Math.cos(a)*(radius-2),Math.sin(a)*(radius-2));c.stroke();}
  // Hinges and a latch make each round weapon container read as a sealed case.
  rect(c,-radius*.57,-radius*.59,7,3,w.color+'88');rect(c,radius*.36,-radius*.59,7,3,w.color+'88');
  drawWeapon(c,tier,0,-2,radius*1.65);
  c.fillStyle=w.color;c.font=`bold ${Math.max(7,radius*.15)}px monospace`;c.textAlign='center';
  c.fillText(String(tier+1).padStart(2,'0'),0,radius*.61);
  rect(c,-5,radius-5,10,3,w.color);
  c.restore();
}


const $ = id => document.getElementById(id);
const canvas = $('game'), ctx = canvas.getContext('2d');
let world, current, next, aim = 260, cooldown = 0, particles = [], floaters = [], paused = false, modal = '', highest = 0, won = false;
let lastMerge = -10000, chain = 0, comboTimer = 0, sound = false, audio;
let bursts = [], aimSample = null, flick = 0, victoryDelay = 0;
const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
let best = 0; try { best = Number(localStorage.getItem('case-drop-best')) || 0; } catch {}
$('best').textContent = best.toLocaleString('uk-UA');
const randomTier = () => { const n = Math.random(); return n < .47 ? 0 : n < .79 ? 1 : n < .95 ? 2 : 3; };

function soundEffect(tier = 0, merge = false) {
  if (!sound) return;
  try {
    audio ||= new (window.AudioContext || window.webkitAudioContext)();
    audio.resume();
    const t = audio.currentTime;
    const notes = merge ? [0,4,7] : [0];
    notes.forEach((note,i) => {
      const osc=audio.createOscillator(), gain=audio.createGain();
      osc.type=merge?'triangle':'sine'; const start=t+i*.055;
      osc.frequency.setValueAtTime((merge?260:140)*2**((tier+note)/12),start);
      if(!merge)osc.frequency.exponentialRampToValueAtTime(45,start+.12);
      gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.065,start+.008);gain.gain.exponentialRampToValueAtTime(.0001,start+.22);
      osc.connect(gain);gain.connect(audio.destination);osc.start(start);osc.stop(start+.25);
    });
  } catch {}
}
function renderNext() {
  const c=$('next').getContext('2d');c.clearRect(0,0,240,170);
  drawCase(c,next,120,84,47,-.12);
  $('next-name').textContent=WEAPONS[next].name;
  $('next-rarity').textContent=WEAPONS[next].rarity;
  $('next-rarity').style.color=WEAPONS[next].color;
}
function updateArsenal() {
  [...$('weapon-list').children].forEach((el,i)=>{el.classList.toggle('locked',i>highest);el.classList.toggle('current',i===highest);});
}
WEAPONS.forEach((w,i)=>{
  const li=document.createElement('li');li.className='weapon-row';
  li.innerHTML=`<canvas width="140" height="74" aria-hidden="true"></canvas><div class="weapon-info"><div class="weapon-name">${w.name}</div><div class="weapon-tier" style="color:${w.color}">${w.rarity}</div></div><span class="weapon-number">${String(i+1).padStart(2,'0')}</span>`;
  $('weapon-list').append(li);drawWeapon(li.querySelector('canvas').getContext('2d'),i,70,37,126);
});
function updateScore() {
  $('score').textContent=String(world.score).padStart(4,'0');$('merges').textContent=world.merges;
  if(world.score>best){best=world.score;$('best').textContent=best.toLocaleString('uk-UA');try{localStorage.setItem('case-drop-best',String(best));}catch{}}
}
function merged(e) {
  const color=WEAPONS[Math.min(e.tier,9)].color;
  const radius=WEAPONS[Math.min(e.tier,9)].radius;
  bursts.push({x:e.x,y:e.y,radius,color,age:0});
  const sparkCount=reducedMotion?8:36;
  for(let i=0;i<sparkCount;i++) {const angle=Math.PI*2*i/sparkCount+Math.random()*.18,speed=2+Math.random()*5;particles.push({x:e.x,y:e.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:1,color,size:1.5+Math.random()*2.5});}
  floaters.push({x:e.x,y:e.y-radius-12,text:`+${e.points}`,life:1,color});
  // The two halves fly apart when the case opens.
  for(const sign of [-1,1])particles.push({x:e.x,y:e.y,vx:sign*4,vy:-3,life:1,color,size:radius*.8,shard:true,rotation:sign*.2});
  const now=performance.now();chain=now-lastMerge<1600?chain+1:1;lastMerge=now;
  if(chain>1){$('combo').textContent=`КОМБО ×${chain}`;$('combo').classList.add('show');comboTimer=90;}
  highest=Math.max(highest,Math.min(e.tier,9));updateScore();updateArsenal();soundEffect(e.tier,true);
  if(e.tier===9&&!won){won=true;victoryDelay=65;}
}
function reset() {
  world=new World(520,630,merged);current=0;next=randomTier();cooldown=0;particles=[];floaters=[];bursts=[];highest=0;won=false;aim=260;chain=0;lastMerge=-10000;comboTimer=0;aimSample=null;flick=0;victoryDelay=0;
  $('combo').classList.remove('show');closeModal();updateScore();renderNext();updateArsenal();
}
function drop() {
  if(paused||world.over||cooldown>0)return;
  const body=world.add(current,aim,48);
  if(aimSample&&performance.now()-aimSample.time<120){body.vx=flick;body.omega=flick/body.r;}
  flick=0;aimSample=null;
  highest=Math.max(highest,current);current=next;next=randomTier();cooldown=38;renderNext();updateArsenal();soundEffect();
}
function setAim(event) {
  const bounds=canvas.getBoundingClientRect(),x=(event.clientX-bounds.left)*520/bounds.width,time=performance.now();
  if(aimSample&&x!==aimSample.x){const elapsed=time-aimSample.time;flick=elapsed>0&&elapsed<120?Math.max(-3.5,Math.min(3.5,(x-aimSample.x)/elapsed*8)):0;}
  if(!aimSample||x!==aimSample.x)aimSample={x,time};
  aim=x;
}
canvas.addEventListener('pointermove',setAim);
canvas.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();canvas.focus({preventScroll:true});setAim(event);canvas.setPointerCapture(event.pointerId);});
canvas.addEventListener('pointerup',event=>{if(event.button!==0)return;setAim(event);drop();});
canvas.addEventListener('keydown',event=>{
  aimSample=null;flick=0;
  if(['ArrowLeft','ArrowRight',' ','Enter'].includes(event.key))event.preventDefault();
  if(event.key==='ArrowLeft')aim=Math.max(WEAPONS[current].radius+8,aim-18);
  if(event.key==='ArrowRight')aim=Math.min(512-WEAPONS[current].radius,aim+18);
  if((event.key===' '||event.key==='Enter')&&!event.repeat)drop();
});
$('sound').addEventListener('click',()=>{sound=!sound;$('sound').querySelector('span').hidden=sound;$('sound').setAttribute('aria-label',sound?'Вимкнути звук':'Увімкнути звук');$('sound').title=sound?'Вимкнути звук':'Увімкнути звук';if(sound)soundEffect(2,true);});
function showModal(type) {
  modal=type;paused=true;$('overlay').hidden=false;$('modal-cancel').hidden=type!=='restart';
  const content={
    help:['ПОЛЬОВИЙ ПОСІБНИК','Збирай свій арсенал','<p>Рухай мишкою, щоб вибрати місце, і клікай, щоб скинути кейс. На телефоні — наведи пальцем і відпусти.</p><p>Два однакові кейси при зіткненні відкриваються й утворюють одну кращу зброю. Більша зброя — більший кейс!</p><p>Збери <strong>легендарний Karambit</strong>. Якщо кейси залишаться над червоною лінією понад 2,5 секунди — раунд завершиться.</p><p class="modal-controls">Клавіатура: <kbd>←</kbd> <kbd>→</kbd> — рух, <kbd>Пробіл</kbd> — скинути.</p>','Погнали'],
    restart:['НОВИЙ РАУНД','Почати з чистого кейса?','<p>Поточне поле й рахунок скинуться. Твій найкращий результат залишиться.</p>','Почати нову гру'],
    over:['РАУНД ЗАВЕРШЕНО','Арсенал заповнений',`<p>Твій результат</p><div class="modal-score">${world.score}</div><p>Відкрито кейсів: <strong>${world.merges}</strong><br>Найкраща зброя: <strong>${WEAPONS[highest].name}</strong></p>`,'Ще один раунд'],
    win:['★ ЛЕГЕНДАРНИЙ ДРОП','Karambit у твоїх руках!',`<p>Ти пройшов увесь шлях від Glock-18 до легенди. Продовжуй об’єднувати кейси й покращуй рекорд!</p><div class="modal-score">${world.score}</div>`,'Продовжити'],
  }[type];
  $('modal-eyebrow').textContent=content[0];$('modal-title').textContent=content[1];$('modal-content').innerHTML=content[2];$('modal-action').innerHTML=content[3]+' <span>↗</span>';
  $('modal-action').focus({preventScroll:true});
}
function closeModal(){paused=false;modal='';$('overlay').hidden=true;canvas.focus({preventScroll:true});}
$('help').addEventListener('click',()=>{if(!modal)showModal('help');});
$('restart').addEventListener('click',()=>{if(world.bodies.length||world.score)showModal('restart');else reset();});
$('modal-action').addEventListener('click',()=>{if(modal==='over'||modal==='restart')reset();else closeModal();});
$('modal-cancel').addEventListener('click',closeModal);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&['help','restart','win'].includes(modal))closeModal();});

function draw() {
  ctx.clearRect(0,0,520,630);
  const danger=world.dangerTime>0;
  ctx.strokeStyle=danger?'#e87762':'#9c635b60';ctx.lineWidth=danger?2:1;ctx.setLineDash([5,7]);ctx.beginPath();ctx.moveTo(9,112);ctx.lineTo(511,112);ctx.stroke();ctx.setLineDash([]);
  if(danger){ctx.fillStyle=`rgba(224,89,65,${.04+Math.sin(performance.now()/140)*.02})`;ctx.fillRect(0,100,520,85);}
  ctx.strokeStyle='#596a4940';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(8,610);ctx.lineTo(8,622);ctx.lineTo(23,622);ctx.moveTo(497,622);ctx.lineTo(512,622);ctx.lineTo(512,610);ctx.stroke();
  const r=WEAPONS[current].radius,x=Math.max(r+8,Math.min(512-r,aim));
  if(!world.over) {
    let landing=622-r;
    for(const b of world.bodies){const dx=b.x-x;if(Math.abs(dx)<r+b.r){const hit=b.y-Math.sqrt((r+b.r)**2-dx**2);if(hit>48)landing=Math.min(landing,hit);}}
    if(cooldown<=0&&!paused){
      ctx.strokeStyle='#bdcfa730';ctx.setLineDash([3,7]);ctx.beginPath();ctx.moveTo(x,48+r);ctx.lineTo(x,landing);ctx.stroke();ctx.setLineDash([]);
      ctx.strokeStyle=WEAPONS[current].color+'35';ctx.beginPath();ctx.arc(x,landing,r,0,Math.PI*2);ctx.stroke();
    }
    drawCase(ctx,current,x,48,r,0,cooldown>0?.3:1);
    ctx.fillStyle='#e8b05f';ctx.beginPath();ctx.moveTo(x-4,7);ctx.lineTo(x+4,7);ctx.lineTo(x,12);ctx.fill();
  }
  for(const b of world.bodies){
    let scale=b.born<12?(.86+Math.min(b.born/12,1)*.14):1;
    if(b.merged&&!reducedMotion&&b.born<30){const t=b.born/30;scale=1-.32*Math.cos(t*Math.PI*3)*Math.exp(-t*4);}
    drawCase(ctx,b.tier,b.x,b.y,b.r*scale,b.angle);
  }
  for(const burst of bursts){
    const t=burst.age/42,fade=(1-t)**2;
    ctx.save();ctx.globalCompositeOperation='lighter';
    if(burst.age<13){
      const glowRadius=burst.radius*(1.5+t*2),glow=ctx.createRadialGradient(burst.x,burst.y,0,burst.x,burst.y,glowRadius);
      glow.addColorStop(0,'#fff9df');glow.addColorStop(.25,burst.color);glow.addColorStop(1,burst.color+'00');
      ctx.globalAlpha=(1-burst.age/13)*(reducedMotion?.15:.6);ctx.fillStyle=glow;
      ctx.beginPath();ctx.arc(burst.x,burst.y,glowRadius,0,Math.PI*2);ctx.fill();
    }
    ctx.globalAlpha=fade*(reducedMotion?.3:1);ctx.strokeStyle=burst.color;ctx.lineWidth=4*(1-t)+.5;
    ctx.beginPath();ctx.arc(burst.x,burst.y,burst.radius*(.7+t*(reducedMotion?.4:2.3)),0,Math.PI*2);ctx.stroke();
    if(!reducedMotion){
      ctx.globalAlpha=fade*.55;ctx.lineWidth=1.5;ctx.strokeStyle='#fff3d2';
      ctx.beginPath();ctx.arc(burst.x,burst.y,burst.radius*(.5+t*1.6),0,Math.PI*2);ctx.stroke();
    }
    ctx.restore();
  }
  for(const p of particles){ctx.save();ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;if(p.shard){ctx.translate(p.x,p.y);ctx.rotate(p.rotation*(1-p.life)*8);ctx.strokeStyle=p.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,p.size,Math.PI*.15,Math.PI*.85);ctx.stroke();}else{
    ctx.globalCompositeOperation='lighter';ctx.strokeStyle=p.color;ctx.lineWidth=p.size*p.life;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(p.x-p.vx*2,p.y-p.vy*2);ctx.lineTo(p.x,p.y);ctx.stroke();
  }ctx.restore();}
  for(const f of floaters){ctx.globalAlpha=Math.max(0,f.life);ctx.fillStyle=f.color;ctx.font='bold 20px monospace';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y);}ctx.globalAlpha=1;
  $('status').textContent=world.over?'РАУНД ЗАВЕРШЕНО':paused?'ПАУЗА':danger?'ОБЕРЕЖНО, МЕЖА!':cooldown>0?'КЕЙС У ПОЛЬОТІ':'ГОТОВИЙ ДО ДРОПУ';
  $('status').style.color=danger?'#e77666':'';
}
let previous=performance.now(),accumulator=0;
function frame(now) {
  const elapsed=Math.min(now-previous,50);previous=now;
  if(!paused&&!document.hidden){
    accumulator+=elapsed;
    while(accumulator>=1000/60){
      world.step();cooldown=Math.max(0,cooldown-1);
      for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.065;p.life-=p.shard?.025:.03;}
      for(const f of floaters){f.y-=.65;f.life-=.018;}
      for(const burst of bursts)burst.age++;
      bursts=bursts.filter(burst=>burst.age<42);
      particles=particles.filter(p=>p.life>0);floaters=floaters.filter(f=>f.life>0);
      if(comboTimer>0&&--comboTimer===0)$('combo').classList.remove('show');
      accumulator-=1000/60;
      if(world.over){showModal('over');break;}
      if(victoryDelay>0&&--victoryDelay===0){showModal('win');break;}
      if(paused)break;
    }
  }else accumulator=0;
  draw();requestAnimationFrame(frame);
}
reset();requestAnimationFrame(frame);

})();
